<template>
    <v-container grid-list-md>
        <v-layout row wrap align-center justify-center>
            <v-flex xs8 sm8>
                <v-form ref="form" v-model="valid">
                    
                    <autocomplete v-on:set-value="onSetProvider" :label="'Поставщик'" :items="providers" :filedValue="invoice.Provider" />

                    <v-textarea
                        name="description"
                        v-model="invoice.InvoiceNote"
                        box
                        label="Примечания к поставке"
                        auto-grow
                        value=""
                    ></v-textarea>

                    <v-text-field
                    v-model="invoice.TotalSumm"
                    label="Общая сумма"
                    required
                    clearable>
                    </v-text-field> 
                    
                    <v-spacer></v-spacer>

                    <v-flex xs12 sm6 md4>
                        <v-menu
                            :close-on-content-click="false"
                            v-model="menu2"
                            :nudge-right="40"
                            lazy
                            transition="scale-transition"
                            offset-y
                            full-width
                            min-width="290px"
                        >
                            <v-text-field
                            slot="activator"
                            v-model="invoice.Date"
                            label="Дата поставки"
                            prepend-icon="event"
                            readonly
                            ></v-text-field>
                            <v-date-picker v-model="invoice.Date" @input="menu2 = false"></v-date-picker>
                        </v-menu>
                    </v-flex>

                    <div class="headline">Позиции:</div>
                    <invoice-goods :items="invoice.InvoiceGoods"></invoice-goods>
                    <v-btn
                    :disabled="!valid"
                    @click="save">
                    Обновить
                    </v-btn>
                </v-form>
            </v-flex>
        </v-layout>
    </v-container>
</template>

<script>
import Autocomplete from '../components/TextFieldAuto'
import InvoiceGoods from '../components/Invoice/invoiceGoodsUpdate'
export default {
    data(){
        return{
            valid: true,
            nameRules: [
                v => !!v || 'Обязательно к заполнению',
                v => (v && v.length <= 100) || 'Не более 100 символов',
                v => (v && v.length > 0) || 'Не более 100 символов'
            ],
            thumbnail: null,
            showPreview: false,
            
        }
    },
    props:{
        'id':{
            type: Number,
            required: true
        }
    },
    created(){
        this.$http.get('https://localhost:44346/api/invoices/' + this.id)
        .then(response => {
            response.data.Date = response.data.Date.substring(0, 10)
            this.$store.commit('setInvoiceDetail', response.data)
        })
        .catch(error => {
            console.log(error)
        })
    },
    mounted(){
    },
    computed:{
        invoice(){
            return this.$store.getters.getInvoiceDetail
        },
        providers(){
            return this.$store.getters.getProviders
        }
    },
    methods:{
        save(){
        this.$http.post('https://localhost:44346/api/invoices/update', this.invoice)
        .then(response => {
            console.log(response);
            this.$router.go(-1)
            this.$notify({
                group: 'foo',
                type: 'success',
                title: 'Invoice updated.',
                text: 'Waer! it`s ok!',
                duration: 10000
            });
        })
        .catch(error => {
            console.log(error)
            this.$notify({
                group: 'foo',
                type: 'error',
                title: 'Something went wrong. Try again.',
                text: 'Waer! it`s ok!',
                duration: 10000
            });
        })
        },
        // remove(){
        //     //this.$router.push('collections')
        //     this.$http.post('https://localhost:44346/api/carpets/remove', this.carpet)
        //     .then(response => {
        //         this.$router.go(-1)
        //     })
        //     .catch(error => {
        //         console.log(error)
        //     })
        // },
        clear(){
            this.$router.go(-1)
        },
        onSetProvider(argument){
            this.invoice.Provider = argument
        }
    },
    components:{
        Autocomplete,
        InvoiceGoods,
    }
}
</script>

<style lang="sass" scoped>
    img
        max-width: 100%
</style>