<script>
  export default {
    name: 'autocomplete',

    props: {
      items: {
        type: Array,
        required: false,
        default: () => [],
      },
      isAsync: {
        type: Boolean,
        required: false,
        default: false,
      },
      label:{
          type: String,
          required: true
      },
      filedValue:{
        type: String,
        required: false,
        default: () => ''
      },
      aCompleteType: {
        type: String,
        required: false,
        default: () => ''
      }
    },

    data() {
      return {
        isComplex: false,
        isOpen: false,
        results: [],
        search: '',
        isLoading: false,
        arrowCounter: 0,
        nameRules: [
            v => !!v || 'Обязательно к заполнению',
            v => (v && v.length <= 100) || 'Не более 100 символов',
            v => (v && v.length > 0) || 'Не более 100 символов'
        ],
      };
    },

    methods: {
      onChange() {
        // Let's warn the parent that a change was made
        // this.$emit('set-value', this.search);

        // Is the data given by an outside ajax request?
        if (this.isAsync) {
          this.isLoading = true;
        } else {
          // Let's  our flat array
          this.filterResults();
          this.isOpen = true;
        }
      },

      filterResults() {
        // first uncapitalize all the things
        if(this.items != null){
            this.results = this.items.filter((item) => {
              return item.Design.toLowerCase().indexOf(this.search.toLowerCase()) > -1;
            });
        }
      },
      setResult(result) {
        this.search = result;
        this.isOpen = false;
        this.$emit('set-value', this.search);
      },
      onArrowDown(evt) {
        if (this.arrowCounter < this.results.length) {
          this.arrowCounter = this.arrowCounter + 1;
        }
      },
      onArrowUp() {
        if (this.arrowCounter > 0) {
          this.arrowCounter = this.arrowCounter -1;
        }
      },
      onEnter() {
        this.search = this.results[this.arrowCounter];
        this.isOpen = false;
        this.arrowCounter = -1;
      },
      handleClickOutside(evt) {
        if (!this.$el.contains(evt.target)) {
          this.isOpen = false;
          this.arrowCounter = -1;
        }
      }
    },
    watch: {
      items: function (val, oldValue) {
        // actually compare them
        if(val != null && oldValue != null){
          if (val.length !== oldValue.length) {
            this.results = val;
            this.isLoading = false;
          }
        }else if(val != null){
          this.results = val
          this.isLoading = false
        }else{
          this.items = []
        }
      },
      search: function(val, oldValue){
        //   this.$emit('set-value', this.search);
      },
      filedValue: function (val){
        if(this.filedValue != ''){
        this.search = this.filedValue
        }
        if(this.filedValue != null){
          this.search = this.filedValue
        }
      },
      aCompleteType: function(val){
        if(this.aCompleteType.length > 0){
          this.isComplex = true
        }else{
          this.isComplex = false
        }
      }
    },
    created(){
      
    },
    mounted() {
      if(this.filedValue != ''){
        this.search = this.filedValue
      }
      document.addEventListener('click', this.handleClickOutside)
      if(this.filedValue != null){
        this.search = this.filedValue
      }

      if(this.aCompleteType.length > 0){
        this.isComplex = true
      }else{
        this.isComplex = false
      }
    },
    destroyed() {
      document.removeEventListener('click', this.handleClickOutside)
    }
  };
</script>

<template>
  <div class="autocomplete">
        <v-text-field
            v-model="search"
            :label="this.label"
            @input="onChange"
            @keydown.down="onArrowDown"
            @keydown.up="onArrowUp"
            @keydown.enter="onEnter"
            required
            clearable>
        </v-text-field>
    <!-- <input
      type="text"
      @input="onChange"
      v-model="search"
      @keydown.down="onArrowDown"
      @keydown.up="onArrowUp"
      @keydown.enter="onEnter"
    /> -->
    <ul
      id="autocomplete-results"
      v-show="isOpen"
      class="autocomplete-results"
    >
      <li
        class="loading"
        v-if="isLoading"
      >
        Loading results...
      </li>
      <li
        v-else
        v-for="(result, i) in results"
        :key="i"
        @click="setResult(result)"
        class="autocomplete-result"
        :class="{ 'is-active': i === arrowCounter }"
      >
        <span v-if="isComplex">{{ result.CollectionName + ' || ' + result.Design}}</span>
        <span v-else>{{result}}</span>
      </li>
    </ul>
  </div>
</template>

<style>
  .autocomplete {
    position: relative;
  }

  .autocomplete-results {
    padding: 0;
    margin: 0;
    border: 1px solid #eeeeee;
    height: 120px;
    overflow: auto;
    width: 100%;
  }

  .autocomplete-result {
    list-style: none;
    text-align: left;
    padding: 4px 2px;
    cursor: pointer;
  }

  .autocomplete-result.is-active,
  .autocomplete-result:hover {
    background-color: #4AAE9B;
    color: white;
  }

</style>