<template>
    <v-card color="info" class="white--text">
        <v-container fluid>
            <v-layout row md12>
                <v-flex xs12 sm12>
                <v-card-title>
                    <div>
                    <div class="headline">{{carpet.Collection.Name}}</div>
                    <div>Страна: {{carpet.Collection.Country}}</div>
                    <div>Плотность: {{carpet.Collection.Density}}</div>
                    <div>Производитель: {{carpet.Collection.Manufacturer}}</div>
                    <div>Материал: {{carpet.Collection.Material}}</div>
                    <div>Высота ворса: {{carpet.Collection.PileHeight}}</div>
                    <div>Ссылка: {{carpet.Collection.Url}}</div>
                    </div>
                </v-card-title>
                </v-flex>
                <v-flex xs12 sm12>
                    <div class="headline">Типы размеров:</div>

                        <v-checkbox
                        v-model="carpet.LaneSize"
                        label="Прямые">
                        </v-checkbox>

                        <add-size v-on:set-sizes="onSetLane" :items="carpet.DefaultSizesLane" v-show="carpet.LaneSize"></add-size>

                        <v-checkbox
                        v-model="carpet.ClassicSize"
                        label="Классические">
                        </v-checkbox>

                        <add-size v-on:set-sizes="onSetClassic" :items="carpet.DefaultSizesClassic" v-show="carpet.ClassicSize"></add-size>

                        <v-checkbox
                        v-model="carpet.RoundSize"
                        label="Круги">
                        </v-checkbox>

                        <add-size v-on:set-sizes="onSetRound" :items="carpet.DefaultSizesRound" v-show="carpet.RoundSize"></add-size>

                        <v-checkbox
                        v-model="carpet.ComplectSize"
                        label="Комплекты">
                        </v-checkbox>

                        <add-size v-on:set-sizes="onSetComplect" :items="carpet.DefaultSizesComplect" v-show="carpet.ComplectSize"></add-size>
                </v-flex>
            </v-layout>
            <v-btn @click="saveSizes">Обновить Размеры</v-btn>
        </v-container>
    </v-card>
</template>

<script>
import AddSize from '../AddSize'
export default {
    props:{
        "carpet":{
            type: Object,
            required: true
        }
    },
    methods:{
        onSetLane(argument){
            this.carpet.DefaultSizesLane = argument
        },
        onSetClassic(argument){
            this.carpet.DefaultSizesClassic = argument
        },
        onSetRound(argument){
            this.carpet.DefaultSizesRound = argument
        },
        onSetComplect(argument){
            this.carpet.DefaultSizesComplect = argument
        },
        saveSizes(){
            this.$http.post('https://localhost:44346/api/carpets/ReGenerateCartpetSizes', this.carpet)
            .then(response => {

            }).catch(error => {
                console.log(error)
            })
        }
    },
    components:{
        AddSize
    }
}
</script>

<style lang="sass" scoped>
.layout
    flex-wrap: wrap
</style>