<template>
    <v-container>
        <v-layout row wrap>

        <!-- <v-text-field
            v-model="Sizes"
            label=" Размеры |Прямые| ">
        </v-text-field> -->

        <v-flex xs4 sm4>
            <v-text-field
                label="Высота"
                type="number"
                v-model="Width"
                outline>
            </v-text-field>
        </v-flex>

        <v-flex xs4 sm4>
            <v-text-field
                label="Ширина"
                type="number"
                v-model="Height"
                outline>
            </v-text-field>
        </v-flex>

        <v-flex xs4 sm4>
            <v-btn fab dark color="indigo" @click="addSize">
                <v-icon dark>add</v-icon>
            </v-btn>
        </v-flex>

        <v-flex d-flex sm3 md3 v-for="size in Sizes" :key="size.id">
            <div class="size-card">
                <span class="size-card__item">{{size.w}}</span>
                <span class="size-card__delim">X</span>
                <span class="size-card__item">{{size.h}}</span>
                <v-btn flat color="error" @click="removeSize" :value="size.id">Удалить</v-btn>
            </div>
        </v-flex>

        </v-layout>
    </v-container>
</template>

<script>
export default {
    props: {
        items: {
            type: String,
            required: false,
            default: () => '',
        },
        isAsync: {
            type: Boolean,
            required: false,
            default: false,
        }
    },
    data() {
        return {
            Sizes: [],
            SizesStr: '',
            Width: null,
            Height: null,
            updating: false
        }
    },
    mounted(){
        if(this.items != '' && this.items != null){
            console.log("Mounted!");
            var lastChar = this.items.substr(this.items.length - 1)
            let str = ''
            if(lastChar === '/'){
                str = this.items.slice(0, -1);
            }else{
                str = this.items
            }
            let elements = str.split('/');
            console.log(str)
            console.log(elements)
            this.Sizes = []
            elements.forEach( (element) => {
                console.log(element)
                let wh = element.split('x')[0]
                let vh = element.split('x')[1]

                let size = {
                    'w': wh, 
                    'h': vh,
                    'id': wh + 'x' + vh
                }
                this.Sizes.push(size)
            })

            // this.SizesStr = ''
            // let tString = ''
            // for (let i = 0; i < this.Sizes.length; i++) {
            //     const element = this.Sizes[i];

            //     tString += element.id + '/'
            // }
            // this.SizesStr = tString
            this.SizesStr = this.items
            console.log("Mounted! END!");
        }
    },
    computed:{
        // Sizes(){
        //     let elements = this.items.split('/')
        //     let arr = []
        //     elements.forEach( (element) => {
        //         let wh = element.split('x')[0]
        //         let vh = element.split('x')[1]

        //         let size = {
        //             'w': wh, 
        //             'h': vh,
        //             'id': wh + 'x' + vh
        //         }
        //         arr.push(size)
        //     })
        //     return arr
        // },
        // SizesStr(){
        //     let tString = ''
        //     for (let i = 0; i < this.Sizes.length; i++) {
        //         const element = this.Sizes[i];

        //         tString += element.id + '/'
        //     }
            
        //     return tString
        // }
    },
    methods: {
        addSize(){
            let size = {
                'w': this.Width, 
                'h': this.Height,
                'id': this.Width + 'x' + this.Height
            }
            if(this.Sizes.filter(o => o.id === size.id).length == 0){
                this.Sizes.push(size)
            }
            this.SizesStr = ''
            for (let i = 0; i < this.Sizes.length; i++) {
                const element = this.Sizes[i];

                this.SizesStr += element.id + '/'
            }
            this.$emit('set-sizes', this.SizesStr)
        },
        removeSize(event){
            let id = event.target.parentNode.value

            // for (let i = 0; i < this.Sizes.length; i++) {
            //     const element = this.Sizes[i];

            //     if(element.id === id){
            //         this.Sizes.splice(i, 1)
            //     }
            // }

            // this.SizesStr = ''
            // for (let i = 0; i < this.Sizes.length; i++) {
            //     const element = this.Sizes[i];

            //     this.SizesStr += element.id + '/'
            // }

            let beforeRemove = this.SizesStr.length
            this.SizesStr = this.SizesStr.replace(id + '/','')
            if(beforeRemove == this.SizesStr.length){
               this.SizesStr = this.SizesStr.replace(id,'') 
            }
            this.$emit('set-sizes', this.SizesStr)
        }
    },
    watch:{
        // SizesStr: function(val, oldValue){
        //     this.$emit('set-sizes', this.SizesStr);
        // },
        items: function(val, oldValue){
            if(this.items != '' && this.items != null){
                console.log("Watched!");
                var lastChar = this.items.substr(this.items.length - 1)
                let str = ''
                if(lastChar === '/'){
                    str = this.items.slice(0, -1);
                }else{
                    str = this.items
                }
                let elements = str.split('/');
                this.Sizes = []
                elements.forEach( (element) => {
                    let wh = element.split('x')[0]
                    let vh = element.split('x')[1]

                    let size = {
                        'w': wh, 
                        'h': vh,
                        'id': wh + 'x' + vh
                    }
                    this.Sizes.push(size)
                })

                // this.SizesStr = ''
                // let tString = ''
                // for (let i = 0; i < this.Sizes.length; i++) {
                //     const element = this.Sizes[i];

                //     tString += element.id + '/'
                // }
                this.SizesStr = this.items
            }
        }
    }
}
</script>

<style lang="sass" scoped>
.size-card
    padding: 10px
    &__item
        font-size: 20px
</style>