import Vue from 'vue'
import Router from 'vue-router'
import Home from './views/Home.vue'
import Collections from '@/views/Collections.vue'
import Designs from '@/views/Designs.vue'
import Users from '@/views/Users.vue'
import Orders from '@/views/Orders.vue'
import OrderDetail from '@/views/OrderDetail.vue'
import OrderCreate from '@/views/OrderCreate.vue'
import CollectionDetail from '@/views/CollectionDetails.vue'
import CollectionCreate from '@/views/CollectionCreate.vue'
import DesignDetail from '@/views/DesignDetail.vue'
import DesignCreate from '@/views/DesignCreate.vue'
import Invoices from '@/views/Invoices.vue'
import InvoiceCreate from '@/views/InvoiceCreate.vue'
import InvoiceDetail from '@/views/InvoiceDetail'

import Courses from '@/views/Courses.vue'
import Account from '@/views/Account.vue'


Vue.use(Router)

export default new Router({
  mode: 'history',
  base: process.env.BASE_URL,
  routes: [
    {
      path: '/',
      name: 'home',
      component: Home
    },
    {
      path: '/collections',
      name: 'collectiions',
      component: Collections
    },
    {
      path: '/collection/:id',
      name: 'collection',
      props: true,
      component: CollectionDetail
    },
    {
      path: '/collectionCreate',
      name: 'collectionCreate',
      component: CollectionCreate
    },
    {
      path: '/designs',
      name: 'designs',
      component: Designs
    },
    {
      path: '/design/:id',
      name: 'design',
      props: true,
      component: DesignDetail
    },
    {
      path: '/designCreate',
      name: 'designCreate',
      component: DesignCreate
    },
    {
      path: '/invoices',
      name: 'invoices',
      component: Invoices
    },
    {
      path: '/invoice/:id',
      name: 'invoice',
      props: true,
      component: InvoiceDetail
    },
    {
      path: '/invoiceCreate',
      name: 'invoiceCreate',
      component: InvoiceCreate
    },
    {
      path: '/users',
      name: 'users',
      component: Users
    },
    {
      path: '/Orders',
      name: 'orders',
      component: Orders
    },
    {
      path: '/Order/:id',
      name: 'order',
      props: true,
      component: OrderDetail
    },
    {
      path: '/OrderCreate',
      name: 'ordercreate',
      component: OrderCreate
    },
    {
      path: '/about',
      name: 'about',
      // route level code-splitting
      // this generates a separate chunk (about.[hash].js) for this route
      // which is lazy-loaded when the route is visited.
      component: () => import(/* webpackChunkName: "about" */ './views/About.vue')
    },
    {
      path: '/courses',
      name: 'courses',
      component: Courses
    },
    {
      path: '/account',
      name: 'account',
      component: Account
    },
  ]
})
