<template>
    <v-container grid-list-md>
        <v-layout row wrap>
            <v-flex xs12 sm12>
                <v-form ref="form" v-model="valid">

                    <autocomplete v-on:set-value="onSetProvider" :label="'Поставщик'" :items="providers" />

                    <v-textarea
                        name="description"
                        v-model="invoice.InvoiceNote"
                        box
                        label="Примечания к поставке"
                        auto-grow
                        value=""
                    ></v-textarea>

                    <v-text-field
                    v-model="invoice.TotalSumm"
                    :rules="nameRules"
                    label="Общая сумма"
                    required
                    clearable>
                    </v-text-field> 
                    
                    <v-spacer></v-spacer>

                    <v-flex xs12 sm6 md4>
                        <v-menu
                            :close-on-content-click="false"
                            v-model="menu2"
                            :nudge-right="40"
                            lazy
                            transition="scale-transition"
                            offset-y
                            full-width
                            min-width="290px"
                        >
                            <v-text-field
                            slot="activator"
                            v-model="invoice.Date"
                            label="Дата поставки"
                            prepend-icon="event"
                            readonly
                            ></v-text-field>
                            <v-date-picker v-model="invoice.Date" @input="menu2 = false"></v-date-picker>
                        </v-menu>
                    </v-flex>

                    <div class="headline">Позиции:</div>
                    <invoice-goods></invoice-goods>
                    <v-btn
                    :disabled="!valid"
                    @click="save">
                    Сохранить
                    </v-btn>
                    <v-btn @click="clear">Отмена</v-btn>
                    <v-btn @click="test">test</v-btn>
                </v-form>
            </v-flex>
        </v-layout>
    </v-container>
</template>

<script>
import Autocomplete from '../components/TextFieldAuto'
import InvoiceGoods from '../components/Invoice/InvoiceGoods'
export default {
    data(){
        return{
            valid: true,
            nameRules: [
                v => !!v || 'Обязательно к заполнению',
                v => (v && v.length <= 100) || 'Не более 100 символов',
                v => (v && v.length > 0) || 'Не более 100 символов'
            ],
            sampleRules: [
                v => !!v || 'Обязательно к заполнению',
                v => (v && v.length <= 100) || 'Не более 100 символов'
            ],
            temporaryArray: [],
            invoice :{
                Date: null,
                InvoiceNote: null,
                Provider: null,
                TotalSumm: null,
                InvoiceGoods: null
            }
        }
    },
    computed: {
        providers(){
            return this.$store.getters.getProviders
        },
        invoiceGoods(){
            return this.$store.getters.getInvoiceGoods
        }
    },
    methods:{
        // http://admin.krim-kover.ru/api/values/check
        // https://localhost:44312/api/values/check
        test(){
            this.$http.get('http://admin.krim-kover.ru/api/values/check',
            {headers: {
            'Access-Control-Allow-Origin': '*',
            },
            dataType: 'json'})
            .then(response => {
                console.log(response);
            })
            .catch(error => {
                console.log(error)
            })
        },
        save(){
            this.dataPrepearing()
            console.log(this.temporaryArray)
            this.$http.post('https://localhost:44346/api/invoices/create', this.invoice)
            .then(response => {
                console.log(response);
                this.$store.commit('addInvoice', response.data);
                this.$router.go(-1)
                this.$notify({
                    group: 'foo',
                    type: 'success',
                    title: 'Collection created.',
                    text: 'Waer! it`s ok!',
                    duration: 10000
                });
            })
            .catch(error => {
                console.log(error)
                
                this.$notify({
                    group: 'foo',
                    type: 'error',
                    title: 'Collection creation failed.',
                    text: 'Something went wrong. Please try again.',
                    duration: 10000
                });
            })
        },
        clear(){
            this.$router.go(-1)
        },
        onSetProvider(argument){
            this.invoice.Provider = argument
        },
        dataPrepearing(){
            class GoodsReceipts {
                constructor(date, count, invId, carpetId, price) {
                    this.Date = date;
                    this.Count = count;
                    this.ConsignmentInvoiceId = invId;
                    this.DirectSizeCarpetId = carpetId;
                    this.PurchasePrice = price;
                }
            }

            this.invoiceGoods.forEach(element => {
                let temp = new GoodsReceipts(element.Date, element.invoice, 0, element.DirectSizeCarpetId, element.price);
                this.temporaryArray.push(temp)   
            })

            this.invoice.InvoiceGoods = this.temporaryArray
        }
    },
    components: {
        Autocomplete,
        InvoiceGoods
    }
}
</script>

