export default {
    state: {
        access_token: null,
        user: null,
        clients: null
    },
    mutations: {
        login (state, token){
            state.access_token = token
        },
        setClients (state, data){
            state.clients = data
        },
        setUpUser (state, person){
            state.user = person
        }
    },
    getters:{
        getClients: (state) => state.clients,
        getCurrentUser: (state) => state.user
    }
}