<template>
    <v-container>
        <v-layout row wrap>

        <v-flex xs12 sm12>
            <v-container fluid>
                <v-layout row>
                    <v-flex md5>
                    <autocomplete v-on:set-value="onSetDesign" :label="'Дизайн'" :items="carpets" :aCompleteType="'Carpet'" />
                    </v-flex>
                    <v-flex md5>
                    <v-select label="Размер" v-if="carpet" :items="carpet.Sizes" v-model="chosenSize">
                        <template slot="selection" slot-scope="data">
                            {{ data.item.Name }}
                        </template>
                        <template slot="item" slot-scope="data">
                            {{ data.item.Name }}
                        </template>
                    </v-select>
                    </v-flex>
                    <v-flex md2 justify-end>
                    <v-spacer></v-spacer>
                    <v-btn flat color="orange" @click.prevent="addSize">Добавить</v-btn>
                    </v-flex>
                </v-layout>
            </v-container>
        </v-flex>

        <v-flex d-flex sm3 md3 v-for="item in sizes" :key="item.DirectSizeCarpetId">

            <v-card>
                <v-img
                :src="'http://krim-kover.ru' + item.Carpet.Thumbnail"
                aspect-ratio="1.35"
                ></v-img>

                <v-card-title primary-title>
                <div>
                    <h3 class="headline mb-0">{{ item.Carpet.Collection.Name }}</h3>
                    <div>{{ item.Carpet.Design }}</div>
                    <div> {{ item.Name }} </div>
                    <div> {{ item.SizeType }} </div>
                    <v-text-field
                        label="Кол-во"
                        type="number"
                        v-model="item.Count"
                    ></v-text-field>  

                    <v-text-field
                        label="Цена закупки"
                        type="number"
                        v-model="item.PurchasePrice"
                    ></v-text-field>  
                </div>
                </v-card-title>

                <v-card-actions>
                <v-btn flat color="error" @click="removeSize" :value="item.DirectSizeCarpetId">Удалить</v-btn>
                </v-card-actions>
            </v-card>
      
        </v-flex>

        </v-layout>
    </v-container>
</template>

<script>
import Autocomplete from './InvoiceItemAutocomplete'
export default {
    props: {
        items: {
            type: Array,
            required: false,
            default: () => []
        }
    },
    data() {
        return {
            chosenSize: null,
            carpet: null,
            // sizes: []
        }
    },
    mounted(){
        if(this.items != '' && this.items != null){
            this.$store.commit('setInvoiceGoods', this.items );
        }
    },
    computed:{
        carpets(){
            return this.$store.getters.getCarpets
        },
        sizes(){
            return this.$store.getters.getInvoiceGoods
        }
    },
    methods: {
        addSize(){
            this.chosenSize.Carpet = this.carpet
            this.chosenSize.invoice = 0
            this.chosenSize.price = 0
            this.$store.commit('addInvoiceGoods', this.chosenSize);
            // this.sizes.push(this.chosenSize)
            // console.log(this.chosenSize.Carpet.Design)
        },
        removeSize(event){
        },
        onSetDesign(argument){
            this.$http.get('https://localhost:44346/api/carpets/' + argument.CarpetId)
            .then(response => {
                console.log(response.data)
                this.carpet = response.data
            })
            .catch(error => {
                console.log(error)
            })
        },
    },
    watch:{
        sizes: function(val, oldValue){
            this.sizes.forEach(element => {
                element.Carpet = element.DirectSizeCarpet.Carpet
            });
        },
        // carpet: function(val){
        //     this.$http.get('https://localhost:44346/api/carpets/' + this.id)
        //     .then(response => {

        //     })
        //     .catch(error => {
        //         console.log(error)
        //     })
        // }
    },
    components: {
        Autocomplete
    },
    beforeDestroy(){
        this.$store.commit('setInvoiceGoods', new Array() );
    }
}
</script>

<style lang="sass" scoped>
.size-card
    padding: 10px
    &__item
        font-size: 20px
</style>