<template>
<v-container grid-list-md>
    <v-layout row wrap>
      <v-flex xs12 sm12>
        <v-container fluid>
          <v-layout row>
            <v-flex md5>
              <v-text-field label="Поиск" v-model="searchTerm">
              </v-text-field>
            </v-flex>
            <v-flex md5>
              <v-autocomplete
                v-model="collectionTerm"
                :hint="!isEditing ? 'Вводите' : 'Сохранить?'"
                :items="collections"
                :readonly="!isEditing"
                :label="`State — ${isEditing ? 'Editable' : 'Readonly'}`"
                persistent-hint
                prepend-icon="mdi-city"
                item-text="Name">
                  <!-- <template slot="item" slot-scope="{ parent,item, tile }">
                    <v-list-tile-content  > 
                      <v-list-tile-title v-html="'${parent.genFilteredText(item.Name)}'"> 
                      </v-list-tile-title>
                    </v-list-tile-content>
                  </template> -->
              </v-autocomplete>
            </v-flex>
            <v-flex md2 justify-end>
              <v-spacer></v-spacer>
              <v-btn flat color="orange" @click.prevent="addNew">Добавить дизайн</v-btn>
            </v-flex>
          </v-layout>
        </v-container>
      </v-flex>
      <v-flex v-for="carpet in filteredCarpets" :key="carpet.CarpetId" xs12 md12>
        <design :carpet="carpet"></design>
      </v-flex>
    </v-layout>
  </v-container>
</template>

<script>
import Design from '../components/Design/DesignItem'
export default {
  data(){
    return{
      searchTerm: null,
      collectionTerm: null,
      isEditing: true
    }
  },
  mounted(){
   
  },
  computed:{
    carpets(){
      return this.$store.getters.getCarpets
    },
    collections(){
      return this.$store.getters.getCollections
    },
    filteredCarpets(){
      let carpets = this.carpets

      // if(this.clientTerm.length){
      //   //orders = orders.filter(o => this.clientTerm.filter(val => o.clientTerm.indexOf(val) !== -1).length > 0)
      //   let temp
      //   this.clientTerm.forEach(function(element) {
      //     temp += orders.filter(t => t.CustomerName === element)
      //   });
      //   orders = temp
      // }
      
      if(this.searchTerm){
        carpets = carpets.filter(o => o.Design.toString().toLowerCase().indexOf(this.searchTerm.toLowerCase()) >= 0)
      }
      if(this.collectionTerm){
        carpets = carpets.filter(o => o.CollectionName.toLowerCase().indexOf(this.collectionTerm.toLowerCase()) >= 0)
      }

      return carpets
    }
  },
  methods:{
    addNew(){
      this.$router.push('designCreate')
    }
  },
  components:{
    Design
  }
}
</script>

