<template>
<v-container grid-list-md>
    <v-layout row wrap>
      <v-flex xs12 sm12>
        <v-container fluid>
          <v-layout row>
            <v-flex md5>
              <v-text-field label="Поиск" v-model="searchTerm">
              </v-text-field>
            </v-flex>
            <v-flex md5>
              <v-select label="Клиенты" :items="providers" v-model="providerTerm">
              </v-select>
            </v-flex>
            <v-flex md2 justify-end>
              <v-spacer></v-spacer>
              <v-btn flat color="orange" @click.prevent="addNew">Добавить приход</v-btn>
            </v-flex>
          </v-layout>
        </v-container>
      </v-flex>
      <v-flex v-for="invoice in filteredInvoices" :key="invoice.ConsignmentInvoiceId" xs12 md12>
        <invoice :invoice="invoice"></invoice>
      </v-flex>
    </v-layout>
  </v-container> 
</template>

<script>
import Invoice from '../components/Invoice/InvoiceItem'
export default {
data(){
    return{
      searchTerm: null,
      providerTerm: null
    }
  },
  mounted(){

  },
  computed:{
    invoices(){
      return this.$store.getters.getInvoices
    },
    filteredInvoices(){
      let invoices = this.invoices
      
      if(this.searchTerm){
        invoices = invoices.filter(o => o.Date.toString().indexOf(this.searchTerm) >= 0)
      }
      if(this.providerTerm){
        invoices = invoices.filter(o => o.Provider.toLowerCase().indexOf(this.providerTerm.toLowerCase()) >= 0)
      }

      return invoices
    },
    providers(){
      return this.$store.getters.getProviders
    }
  },
  methods:{
    addNew(){
      this.$router.push('invoiceCreate')
    }
  },
  components:{
    Invoice
  }
}
</script>

