<template>
<v-container grid-list-md>
    <v-layout row wrap>
      <v-flex xs12 sm12>
        <v-container fluid>
          <v-layout row>
            <v-flex md5>
              <v-text-field label="Поиск" v-model="searchTerm">
              </v-text-field>
            </v-flex>
            <v-flex md5>
              <v-select label="Страна" :items="countrys" v-model="countryTerm">
              </v-select>
            </v-flex>
            <v-flex md2 justify-end>
              <v-spacer></v-spacer>
              <v-btn flat color="orange" @click.prevent="addNew">Добавить коллекцию</v-btn>
            </v-flex>
          </v-layout>
        </v-container>
      </v-flex>
      <v-flex v-for="collection in filteredCollections" :key="collection.CollectionId" xs12 md12>
        <collection :collection="collection"></collection>
      </v-flex>
    </v-layout>
  </v-container>
</template>

<script>
import Collection from '../components/Collection/CollectionItem'
export default {
  data(){
    return{
      searchTerm: null,
      countryTerm: null
    }
  },
  methods:{

  },
  mounted(){
    
  },
  computed:{
    collections(){
      return this.$store.getters.getCollections
    },
    filteredCollections(){
      let collections = this.collections

      // if(this.clientTerm.length){
      //   //orders = orders.filter(o => this.clientTerm.filter(val => o.clientTerm.indexOf(val) !== -1).length > 0)
      //   let temp
      //   this.clientTerm.forEach(function(element) {
      //     temp += orders.filter(t => t.CustomerName === element)
      //   });
      //   orders = temp
      // }
      
      if(this.searchTerm){
        collections = collections.filter(o => o.Name.toString().toLowerCase().indexOf(this.searchTerm.toLowerCase()) >= 0)
      }
      if(this.countryTerm){
        collections = collections.filter(o => o.Country.toLowerCase().indexOf(this.countryTerm.toLowerCase()) >= 0)
      }

      return collections
    },
    countrys(){
      return this.$store.getters.getCountrys
    }
  },
  methods:{
    addNew(){
      this.$router.push('collectionCreate')
    }
  },
  components:{
    Collection
  }
}
</script>

