<template>
    <v-container grid-list-md>
        <v-layout row wrap>
            <v-flex xs8 sm8>
                <v-form ref="form" v-model="valid">
                    <v-text-field
                    v-model="carpet.Name"
                    label="Название"
                    >
                    </v-text-field>
                    
                    <autocomplete v-on:set-value="onSetColor" :label="'Цвет'" :items="colors" />
                    <!-- <v-text-field
                    v-model="carpet.Color"
                    :rules="nameRules"
                    label="Цвет"
                    required>
                    </v-text-field> -->

                    <autocomplete v-on:set-value="onSetTechColor" :label="'Тех. цвет'" :items="techColors" />
                    <!-- <v-text-field
                    v-model="carpet.techColor"
                    :rules="nameRules"
                    label="Тех. цвет"
                    required>
                    </v-text-field> -->

                    <v-text-field
                    v-model="carpet.Design"
                    :rules="nameRules"
                    label="Дизайн"
                    required>
                    </v-text-field>

                    <autocomplete v-on:set-value="onSetType" :label="'Тип'" :items="types" />
                    <!-- <v-text-field
                    v-model="carpet.Type"
                    :rules="nameRules"
                    label="Тип"
                    required>
                    </v-text-field> -->

                    <autocomplete v-on:set-value="onSetForm" :label="'Форма'" :items="forms" />
                    <!-- <v-text-field
                    v-model="carpet.Form"
                    :rules="nameRules"
                    label="Форма"
                    required>
                    </v-text-field> -->

                    <autocomplete v-on:set-value="onSetDensity" :label="'Плотность'" :items="densitys" />
                    <!-- <v-text-field
                    v-model="carpet.Density"
                    :rules="nameRules"
                    label="Плотность"
                    required>
                    </v-text-field> -->
                    <div>
                        <div class="headline">Коллекция:</div>
                        <select v-model="selectedCollection">
                            <option v-for="option in collections" :key="option.CollectionId">
                                {{ option.Name }}
                            </option>
                        </select>
                        <!-- <span>Коллекция: {{ carpet.Collection.Name  ? carpet.Collection.Name : "Не выбрано" }}</span> -->
                    </div>
                    

                    <v-btn
                    :disabled="!valid"
                    @click="save">
                    Сохранить
                    </v-btn>
                    <v-btn @click="clear">Отменить</v-btn>
                </v-form>
            </v-flex>

            <v-flex xs4 sm4 > 
                <div class="headline">Миниатюра дизайна:</div>
                <!-- <v-text-field label="Select Image" @click='pickFile' v-model='carpet.Thumbnail' prepend-icon='attach_file'></v-text-field> -->
                <input
                    type="file"
                    ref="image"
                    accept="image/*"
                    id="thumbnail"
                    @change="onFilePicked">
                <img :src="thumbnailPreview" v-show="showPreview"/>
                
            </v-flex>

            <v-flex sm12 md12>
                <chosen-collection v-on:set-sizes="onSetSizes" :carpet="carpet" v-if="renderCollection"></chosen-collection>
            </v-flex>
        </v-layout>
    </v-container>
</template>

<script>
import Autocomplete from '../components/TextFieldAuto'
import AddSize from '../components/AddSize'
import ChosenCollection from '../components/Design/ChosenCollection'
export default {
    data(){
        return{
            valid: true,
            nameRules: [
                v => !!v || 'Обязательно к заполнению',
                v => (v && v.length <= 100) || 'Не более 100 символов',
                v => (v && v.length > 0) || 'Не более 100 символов'
            ],
            loadedCollection: null,
            carpet :{
                Color: null,
                Density:null,
                Design: null,
                Form: null,
                Name:null,
                Sizes:null,
                SizesList:null,
                Type:null,
                sizesLock:false,
                techColor:null
            },
            selectedCollection: null,
            renderCollection: false,
            thumbnail: null,
            showPreview: false,
            thumbnailPreview: null
        }
    },
    computed:{
        densitys(){
            return this.$store.getters.getDensitys
        },
        colors(){
            return this.$store.getters.getColors
        },
        techColors(){
            return this.$store.getters.getTechColors
        },
        types(){
            return this.$store.getters.getTypes
        },
        forms(){
            return this.$store.getters.getForms
        },
        collections(){
            return this.$store.getters.getCollections
        }
    },
    watch:{
        selectedCollection: function(val){
            this.renderCollection = false
            //this.carpet.Collection = this.collections.filter(c => c.Name.toLowerCase().indexOf(this.selectedCollection.toLowerCase()) >= 0)[0]
            const fd = new FormData();
            fd.append("id", val)
            this.$http.post('https://localhost:44346/api/filter/GetCollection/', fd)
            .then(response => {
                console.log(response)
                //this.loadedCollection = response.data
                this.carpet.Collection = response.data
                console.log('qq')
                this.carpet.LaneSize = this.carpet.Collection.LaneSize
                this.carpet.ClassicSize = this.carpet.Collection.ClassicSize
                this.carpet.RoundSize = this.carpet.Collection.RoundSize
                this.carpet.ComplectSize = this.carpet.Collection.ComplectSize

                this.carpet.DefaultSizesLane = this.carpet.Collection.DefaultSizesLane
                this.carpet.DefaultSizesClassic = this.carpet.Collection.DefaultSizesClassic
                this.carpet.DefaultSizesRound = this.carpet.Collection.DefaultSizesRound
                this.carpet.DefaultSizesComplect = this.carpet.Collection.DefaultSizesComplect

                this.renderCollection = true
            })
            .catch(error => {
                console.log(error)
            })
            
        }
    },
    methods:{
        save(){
            this.carpet.CollectionId = this.carpet.Collection.CollectionId
            this.carpet.Collection = null
            this.$http.post('https://localhost:44346/api/carpets/create', this.carpet)
            .then(response => {
                this.$store.commit('addCarpet', response.data);
                var files = document.getElementById('thumbnail').files[0];
                if(files != null){
                    const fd = new FormData();
                    fd.append("images", files)
                    fd.append("id", response.data.CarpetId)
                    this.$http.post('https://localhost:44312/api/values/CarpetThumbnailEdit', fd,
                        {
                            headers: {
                                'Content-Type': 'multipart/form-data'
                            }
                        })
                    .then(response => {
                        this.$router.go(-1)
                    }).catch(error => {
                        console.log(error)
                    })
                }
            })
            .catch(error => {
                console.log(error)
            })
        },
        clear(){
        this.$router.go(-1)
        },
        onSetColor(argument){
            this.carpet.Color = argument
        },
        onSetTechColor(argument){
            this.carpet.techColor = argument
        },
        onSetType(argument){
            this.carpet.Type = argument
        },
        onSetForm(argument){
            this.carpet.Form = argument
        },
        onSetDensity(argument){
            this.carpet.Density = argument
        },
        onSetSizes(argument){

        },
        onFilePicked() {
            this.thumbnail = this.$refs.image.files[0]

            let reader  = new FileReader()

            reader.addEventListener("load", function () {
                this.showPreview = true;
                this.thumbnailPreview = reader.result;
            }.bind(this), false);
            this.carpet.Thumbnail = 'http://admin.krim-kover.ru/images/goods_pictures/' + this.carpet.CarpetId + '/' + this.thumbnail.name
            if( this.thumbnail ){
                /*
                    Ensure the file is an image file.
                */
                if ( /\.(jpe?g|png|gif)$/i.test( this.thumbnail.name ) ) {
                    /*
                    Fire the readAsDataURL method which will read the file in and
                    upon completion fire a 'load' event which we will listen to and
                    display the image in the preview.
                    */
                    reader.readAsDataURL( this.thumbnail );
                }
            }

        }
    },
    components: {
        Autocomplete,
        AddSize,
        ChosenCollection
    }
}
</script>

<style lang="sass" scoped>
select
    border: 1px solid
    width: 50%

img
    max-width: 100%
</style>