<template>
  <v-container grid-list-md>
    <v-layout row wrap>
      <v-flex xs12 sm12>
        <v-container fluid>
          <v-layout row>
            <v-flex md5>
              <v-text-field label="Поиск" v-model="searchTerm">
              </v-text-field>
            </v-flex>
            <v-flex md5>
              <v-select label="Клиенты" :items="clients" v-model="clientTerm" item-text="CustomerName">
              </v-select>
            </v-flex>
            <v-flex md2 justify-end>
              <v-spacer></v-spacer>
              <v-btn flat color="orange" @click.prevent="addNew">Добавить заказ</v-btn>
            </v-flex>
          </v-layout>
        </v-container>
      </v-flex>
      <v-flex v-for="order in filteredOrders" :key="order.OrderId" xs12 md12>
        <order :order="order"></order>
      </v-flex>
    </v-layout>
  </v-container>
</template>

<script>
import Order from '../components/Order/OrderItem'
export default {
  data(){
    return{
      searchTerm: null,
      clientTerm: null
    }
  },
  mounted(){
    this.$http.get('https://localhost:44346/api/orders/GetOrders')
    .then(response => {
      console.log(response);
      this.$store.commit('setOrders', response.data);
    })
    .catch(error => {
      console.log(error)
    })

    this.$http.get('https://localhost:44346/api/clients/GetClients')
    .then(response => {
      console.log(response);
      this.$store.commit('setClients', response.data);
    })
    .catch(error => {
      console.log(error)
    })
  },
  computed:{
    orders(){
      return this.$store.getters.getOrders
    },
    filteredOrders(){
      let orders = this.orders

      // if(this.clientTerm.length){
      //   //orders = orders.filter(o => this.clientTerm.filter(val => o.clientTerm.indexOf(val) !== -1).length > 0)
      //   let temp
      //   this.clientTerm.forEach(function(element) {
      //     temp += orders.filter(t => t.CustomerName === element)
      //   });
      //   orders = temp
      // }
      
      if(this.searchTerm){
        orders = orders.filter(o => o.OrderId.toString().toLowerCase().indexOf(this.searchTerm.toLowerCase()) >= 0)
      }
      if(this.clientTerm){
        orders = orders.filter(o => o.ApplicationUser.CustomerName.toLowerCase().indexOf(this.clientTerm.toLowerCase()) >= 0)
      }

      return orders
    },
    clients(){
      return this.$store.getters.getClients
    }
  },
  methods:{
    addNew(){
      this.$router.push('ordercreate')
    }
  },
  components:{
    Order
  }
}
</script>

