<template>
    <v-card color="info" class="white--text">
        <v-container fluid>
        <v-layout row md12>
            <v-flex xs12 sm12>
            <v-card-title>
                <div>
                <div class="headline">{{carpet.Collection.Name}}</div>
                <div>Страна: {{carpet.Collection.Country}}</div>
                <div>Плотность: {{carpet.Collection.Density}}</div>
                <div>Производитель: {{carpet.Collection.Manufacturer}}</div>
                <div>Материал: {{carpet.Collection.Material}}</div>
                <div>Высота ворса: {{carpet.Collection.PileHeight}}</div>
                <div>Ссылка: {{carpet.Collection.Url}}</div>
                </div>
            </v-card-title>
            </v-flex>
            <v-flex xs12 sm12>
                <div class="headline">Типы размеров:</div>

                    <v-checkbox
                    v-model="carpet.Collection.LaneSize"
                    label="Прямые">
                    </v-checkbox>

                    <add-size v-on:set-sizes="onSetLane" :items="carpet.Collection.DefaultSizesLane" v-show="carpet.Collection.LaneSize"></add-size>

                    <v-checkbox
                    v-model="carpet.Collection.ClassicSize"
                    label="Классические">
                    </v-checkbox>

                    <add-size v-on:set-sizes="onSetClassic" :items="carpet.Collection.DefaultSizesClassic" v-show="carpet.Collection.ClassicSize"></add-size>

                    <v-checkbox
                    v-model="carpet.Collection.RoundSize"
                    label="Круги">
                    </v-checkbox>

                    <add-size v-on:set-sizes="onSetRound" :items="carpet.Collection.DefaultSizesRound" v-show="carpet.Collection.RoundSize"></add-size>

                    <v-checkbox
                    v-model="carpet.Collection.ComplectSize"
                    label="Комплекты">
                    </v-checkbox>

                    <add-size v-on:set-sizes="onSetComplect" :items="carpet.Collection.DefaultSizesComplect" v-show="carpet.Collection.ComplectSize"></add-size>
            </v-flex>
        </v-layout>
        </v-container>
    </v-card>
</template>

<script>
import AddSize from '../AddSize'
export default {
    props:{
        "carpet":{
            type: Object,
            required: true
        }
    },
    methods:{
        onSetLane(argument){
            this.carpet.DefaultSizesLane = argument
        },
        onSetClassic(argument){
            this.carpet.DefaultSizesClassic = argument
        },
        onSetRound(argument){
            this.carpet.DefaultSizesRound = argument
        },
        onSetComplect(argument){
            this.carpet.DefaultSizesComplect = argument
        }
    },
    components:{
        AddSize
    }
}
</script>

<style lang="sass" scoped>

</style>
