<template>
<v-container grid-list-md>
    <v-layout row wrap>
      <v-flex xs12 sm12>
        <v-container fluid>
          <v-layout row>
            <v-flex md12 justify-end>
                <v-form
                    ref="form"
                    v-model="valid"
                    lazy-validation
                >
                    <v-text-field
                    v-model="user.uid"
                    :counter="10"
                    :rules="nameRules"
                    label="Name"
                    required
                    ></v-text-field>

                    <v-text-field
                    v-model="user.Login"
                    :counter="10"
                    :rules="nameRules"
                    label="Name"
                    required
                    ></v-text-field>

                    <v-text-field
                    v-model="user.Role"
                    :counter="10"
                    :rules="nameRules"
                    label="Name"
                    required
                    ></v-text-field>

                    <v-checkbox
                    v-model="checkbox"
                    :rules="[v => !!v || 'You must agree to continue!']"
                    label="Do you agree?"
                    required
                    ></v-checkbox>

                    <v-btn
                    :disabled="!valid"
                    color="success"
                    class="mr-4"
                    @click="validate"
                    >
                    Validate
                    </v-btn>

                    <v-btn
                    color="error"
                    class="mr-4"
                    @click="reset"
                    >
                    Reset Form
                    </v-btn>

                    <v-btn
                    color="warning"
                    @click="resetValidation"
                    >
                    Reset Validation
                    </v-btn>
                </v-form>
            </v-flex>
          </v-layout>
        </v-container>
      </v-flex>
      
    </v-layout>
  </v-container>
</template>

<script>
// import Collection from '../components/Collection/CollectionItem'
export default {
    data: () => ({
        valid: true,
        name: '',
        nameRules: [
            v => !!v || 'Name is required',
            v => (v && v.length <= 10) || 'Name must be less than 10 characters',
        ],
        email: '',
        emailRules: [
            v => !!v || 'E-mail is required',
            v => /.+@.+\..+/.test(v) || 'E-mail must be valid',
        ],
        select: null,
        items: [
            'Item 1',
            'Item 2',
            'Item 3',
            'Item 4',
        ],
        checkbox: false,
        }),

        methods: {
        validate () {
            if (this.$refs.form.validate()) {
            this.snackbar = true
            }
        },
        reset () {
            this.$refs.form.reset()
        },
        resetValidation () {
            this.$refs.form.resetValidation()
        },
        },
    mounted(){
        
    },
    computed:{
        user(){
            return this.$store.getters.getCurrentUser
        },
        // countrys(){
        //   return this.$store.getters.getCountrys
        // }
    },
    methods:{
        addNew(){
        this.$router.push('collectionCreate')
        }
    },
    components:{
        // Collection
    }
}
</script>

