<template>
    <v-container grid-list-md v-if="order">

        <v-layout row wrap>
            <v-flex md12>
                <order-information :order="order"></order-information>
            </v-flex>

            <v-flex md12>
                <order-client :client="order.ApplicationUser"></order-client>
            </v-flex>
        </v-layout>

        <v-layout row wrap>
            <div style="display: block;width: 100%;">
                <p class="font-weight-regular display-2"> Позиции заказа</p>
            </div>
            
            <v-spacer class="black"></v-spacer>
            <v-flex md6 v-for="carpet in order.MCarpets" :key="carpet.Count">
                <order-positions :carpet="carpet"></order-positions>
            </v-flex>
        </v-layout>

        <v-layout row wrap>
            <v-flex md12 >
                <v-btn color="success" @click.prevent="save">Сохранить</v-btn>
                <v-btn color="error" @click.prevent="remove">Удалить</v-btn>
            </v-flex>
        </v-layout>

    </v-container>
</template>

<script>
import OrderInformation from '../components/Order/OrderInfo'
import OrderClient from '../components/Order/OrderClient'
import OrderPositions from '../components/Order/OrderPositions'

    export default {
        props:{
            'id':{
                type: Number,
                required: true
            }
        },
        computed:{
            order(){
                return this.$store.getters.getOrderDetail
            }
        },
        mounted(){
            this.$http.get('https://localhost:44346/api/orders/' + this.id)
            .then(response => {
            console.log(response);
            this.$store.commit('setOrderDetail', response.data);
            })
            .catch(error => {
            console.log(error)
            })
        },
        methods:{
            save(){
            this.$http.post('https://localhost:44346/api/orders/update', this.order)
            .then(response => {
            console.log(response);
            })
            .catch(error => {
            console.log(error)
            })
            },
            remove(){
            this.$http.post('https://localhost:44346/api/orders/remove', this.order)
            .then(response => {
            router.push('orders')
            })
            .catch(error => {
            console.log(error)
            })
            }
        },
        components:{
            OrderInformation,
            OrderClient,
            OrderPositions
        }
    }
</script>

