            var data = new FormData();
            var files = document.getElementById('gallery').files;
            let PhotoUrl = ''
            //var files = this.images.concat(this.thumbnails)
            console.log({files})
            for (let x = 0; x < files.length; x++) {
                data.append('file' + x, files[x]);
                PhotoUrl += 'http://admin.krim-kover.ru/images/goods_pictures/' + this.carpetId + '/' + files[x].name + '|'
            }
            this.$store.commit('setGallery', PhotoUrl);
            data.append('id', this.carpetId)
            console.log(this.carpetId)
            this.$http.post('http://admin.krim-kover.ru/api/values/CarpetGalleryEdit', data,
