<template>
    <v-container grid-list-md>
        <v-layout row wrap align-center justify-center>
            <v-flex xs8 sm8>
                <v-form ref="form" v-model="valid">
                    <v-text-field
                    v-model="carpet.Name"
                    label="Название"
                    >
                    </v-text-field>
                    
                    <autocomplete v-on:set-value="onSetColor" :filedValue="carpet.Color" :label="'Цвет'" :items="colors" />

                    <autocomplete v-on:set-value="onSetTechColor" :filedValue="carpet.techColor" :label="'Тех. цвет'" :items="techColors" />

                    <v-text-field
                    v-model="carpet.Design"
                    :rules="nameRules"
                    label="Дизайн"
                    required>
                    </v-text-field>

                    <autocomplete v-on:set-value="onSetType" :filedValue="carpet.Type" :label="'Тип'" :items="types" />

                    <autocomplete v-on:set-value="onSetForm" :filedValue="carpet.Form" :label="'Форма'" :items="forms" />

                    <autocomplete v-on:set-value="onSetDensity" :filedValue="carpet.Density" :label="'Плотность'" :items="densitys" />

                    <v-text-field
                    v-model="carpet.Collection.Name"
                    :rules="nameRules"
                    label="Коллекция"
                    required
                    disabled>
                    </v-text-field>

                    <v-btn
                    :disabled="!valid"
                    @click="save">
                    Сохранить
                    </v-btn>
                    <v-btn @click="remove">Удалить</v-btn>
                </v-form>
            </v-flex>
            <v-flex xs4 sm4 > 
                <div class="headline">Миниатюра дизайна:</div>
                <!-- <v-text-field label="Select Image" @click='pickFile' v-model='carpet.Thumbnail' prepend-icon='attach_file'></v-text-field> -->
                <input
                    type="file"
                    ref="image"
                    accept="image/*"
                    id="thumbnail"
                    @change="onFilePicked">
                <img :src="thumbnailPreview" />
            </v-flex>
            <v-spacer class="black"></v-spacer>
            <gallery :items="carpet.PhotoUrl" :carpetId="carpet.CarpetId"></gallery>
            <v-spacer class="black"></v-spacer>
            <v-flex sm12 md12>
                <design-sizes v-on:set-sizes="onSetSizes" :carpet="carpet"></design-sizes>
            </v-flex>

            <v-flex sm12 md12>
                <div class="headline">Размеры:</div>
                <direct-sizes v-on:set-sizes="onSetSizes" :sizes="carpet.Sizes"></direct-sizes>
            </v-flex>
        </v-layout>
    </v-container>
</template>

<script>
import Autocomplete from '../components/TextFieldAuto'
import DesignSizes from '../components/Design/DesignSizes'
import DirectSizes from '../components/Design/DirectSizes'
import Gallery from '../components/Design/Gallery'
export default {
    data(){
        return{
            valid: true,
            nameRules: [
                v => !!v || 'Обязательно к заполнению',
                v => (v && v.length <= 100) || 'Не более 100 символов',
                v => (v && v.length > 0) || 'Не более 100 символов'
            ],
            thumbnail: null,
            showPreview: false,
            
        }
    },
    props:{
        'id':{
            type: Number,
            required: true
        }
    },
    created(){
        this.$http.get('https://localhost:44346/api/carpets/' + this.id)
        .then(response => {
            this.$store.commit('setCarpetDetail', response.data)
        })
        .catch(error => {
            console.log(error)
        })
    },
    mounted(){
        if(this.carpet.Thumbnail != null && this.carpet.Thumbnail.length > 0){
            if(!this.carpet.Thumbnail.includes('http://')){
                this.thumbnailPreview = 'http://krim-kover.ru/' + this.carpet.Thumbnail
            }
            this.thumbnailPreview = this.carpet.Thumbnail
            this.showPreview = true
        }
    },
    computed:{
        carpet(){
            return this.$store.getters.getCarpetDetail
        },
        densitys(){
            return this.$store.getters.getDensitys
        },
        colors(){
            return this.$store.getters.getColors
        },
        techColors(){
            return this.$store.getters.getTechColors
        },
        types(){
            return this.$store.getters.getTypes
        },
        forms(){
            return this.$store.getters.getForms
        },
        collections(){
            return this.$store.getters.getCollections
        },
        thumbnailPreview(){
            return this.carpet.Thumbnail
        },
        gallery(){
            return this.$store.getters.getGallery
        }
    },
    methods:{
        save(){
        var files = document.getElementById('thumbnail').files[0];
        this.carpet.Thumbnail
        this.$http.post('https://localhost:44346/api/carpets/update', this.carpet)
        .then(response => {
            if(this.thumbnail != null){
                const fd = new FormData();
                
                fd.append('images', files)
                fd.append('id', this.carpet.CarpetId)
                console.log(this.carpet.CarpetId)
                console.log({fd})
                // http://admin.krim-kover.ru/api/values/CarpetThumbnailEdit
                this.$http.post('https://localhost:44312/api/values/CarpetThumbnailEdit', fd,
                    {
                        headers: {
                            'Access-Control-Allow-Origin': '*',
                            'Content-Type': 'multipart/form-data'
                        }
                    })
                .then(response => {
                    console.log(response)
                    this.$router.go(-1)
                }).catch(error => {
                    console.log(error)
                })
            }
        })
        .catch(error => {
            console.log(error)
        })
        },
        remove(){
            //this.$router.push('collections')
            this.carpet.collections = null
            this.$http.post('https://localhost:44346/api/carpets/remove', this.carpet)
            .then(response => {
                this.$router.go(-1)
            })
            .catch(error => {
                console.log(error)
            })
        },
        onSetColor(argument){
            this.carpet.Color = argument
        },
        onSetTechColor(argument){
            this.carpet.techColor = argument
        },
        onSetType(argument){
            this.carpet.Type = argument
        },
        onSetForm(argument){
            this.carpet.Form = argument
        },
        onSetDensity(argument){
            this.carpet.Density = argument
        },
        onSetSizes(argument){

        },
        onFilePicked() {
            this.thumbnail = this.$refs.image.files[0]
            
            let reader  = new FileReader()

            reader.addEventListener("load", function () {
                this.showPreview = true;
                // this.carpet.Thumbnail = reader.result;
            }.bind(this), false);
            this.carpet.Thumbnail = 'http://admin.krim-kover.ru/images/goods_pictures/' + this.carpet.CarpetId + '/' + this.thumbnail.name
            if( this.thumbnail ){
                /*
                    Ensure the file is an image file.
                */
                if ( /\.(jpe?g|png|gif)$/i.test( this.thumbnail.name ) ) {
                    /*
                    Fire the readAsDataURL method which will read the file in and
                    upon completion fire a 'load' event which we will listen to and
                    display the image in the preview.
                    */
                    reader.readAsDataURL( this.thumbnail );
                }
            }
        }
    },
    components:{
        Autocomplete,
        DesignSizes,
        DirectSizes,
        Gallery
    },
    watch: {
        gallery: function(val){
            this.carpet.PhotoUrl = val
        },
    }
}
</script>

<style lang="sass" scoped>
    img
        max-width: 100%
</style>