<template>
  <v-container fluid fill-height>
    <v-layout align-center justify-center>
      <v-flex xs12 sm8 md4>
        <v-card class="elevation-12">
          <v-toolbar dark color="primary">
            <v-toolbar-title>Войти</v-toolbar-title>
          </v-toolbar>
          <v-card-text>
            <v-form>
              <v-text-field prepend-icon="person" name="login" label="Login" type="email" required v-model="email"></v-text-field>
              <v-text-field id="password" prepend-icon="lock" name="password" label="Password" type="password" required v-model="password"></v-text-field>
            </v-form>
          </v-card-text>
          <v-card-actions>
            <v-spacer></v-spacer>
            <v-btn color="primary" @click.prevent="signin">Войти</v-btn>
          </v-card-actions>
        </v-card>
      </v-flex>
      <div>

      </div>
    </v-layout>
  </v-container>
</template>

<script>

export default {
  data(){
    return{
      email: null,
      password: null
    }
  },
  mounted(){

  },
  methods:{
    signin(){
      var data = {
        grant_type: 'password',
        Login: this.email,
        Password: this.password
      }
      console.log({data});
      this.$http.post('https://localhost:44307/api/Account/token', data)
      .then(response => {
        console.log(response);
        this.$store.commit('login', response.data.access_token);
        this.$store.commit('setUpUser', response.data.person);
        this.$http.defaults.headers.common['Authorization'] = 'Bearer ' + this.$store.state.UserModule.user.access_token;
        // this.$router.push({ path: 'orders' })
      })
      .catch(error => {
        console.log(error)
      })
    }
  }
}
</script>
