<template>
    <v-container grid-list-md>
        <v-layout row wrap>
            <v-flex xs12 sm12>
                <v-form ref="form" v-model="valid">
                   <v-text-field
                    v-model="collection.Name"
                    :rules="nameRules"
                    label="Название"
                    required
                    clearable>
                    </v-text-field> 

                    <autocomplete v-on:set-value="onSetCountry" :filedValue="collection.Country" :label="'Страна'" :items="countrys" />
                    <!-- <v-text-field
                    v-model="collection.Country"
                    :rules="nameRules"
                    label="Страна"
                    required
                    clearable>
                    </v-text-field> -->
                    <autocomplete v-on:set-value="onSetDensity" :filedValue="collection.Density" :label="'Плотность'" :items="densitys" />
                    <!-- <v-text-field
                    v-model="collection.Density"
                    :rules="nameRules"
                    label="Плотность"
                    required
                    clearable>
                    </v-text-field> -->
                    <autocomplete v-on:set-value="onSetManufacturer" :filedValue="collection.Manufacturer" :label="'Производитель'" :items="manufacturers" />
                    <!-- <v-text-field
                    v-model="collection.Manufacturer"
                    :rules="nameRules"
                    label="Производитель"
                    required
                    clearable>
                    </v-text-field> -->
                    <autocomplete v-on:set-value="onSetMaterial" :filedValue="collection.Material" :label="'Материал'" :items="materials" />
                    <!-- <v-text-field
                    v-model="collection.Material"
                    :rules="nameRules"
                    label="Материал"
                    required
                    clearable>
                    </v-text-field> -->
                    <autocomplete v-on:set-value="onSetPileHeight" :filedValue="collection.PileHeight" :label="'Высота ворса'" :items="pileHeights" />
                    <!-- <v-text-field
                    v-model="collection.PileHeight"
                    :rules="nameRules"
                    label="Высота ворса"
                    required
                    clearable>
                    </v-text-field> -->

                    <v-text-field
                    v-model="collection.Url"
                    :rules="nameRules"
                    label="Ссылка"
                    required
                    clearable>
                    </v-text-field>

                    <v-textarea
                        name="description"
                        v-model="collection.Description"
                        box
                        label="СЕО описание"
                        auto-grow
                        value=""
                    ></v-textarea>

                    <v-spacer></v-spacer>

                    <div class="headline">Типы размеров:</div>

                    <v-checkbox
                    v-model="collection.LaneSize"
                    label="Прямые">
                    </v-checkbox>

                    <!-- <v-text-field
                    v-model="collection.DefaultSizesLane"
                    :rules="nameRules"
                    label=" Размеры |Прямые| "
                    required v-if="collection.LaneSize">
                    </v-text-field> -->
                    <add-size v-on:set-sizes="onSetLane" :items="collection.DefaultSizesLane" v-if="collection.LaneSize"></add-size>

                    <v-checkbox
                    v-model="collection.ClassicSize"
                    label="Классические">
                    </v-checkbox>

                    <add-size v-on:set-sizes="onSetClassic" :items="collection.DefaultSizesClassic" v-if="collection.ClassicSize"></add-size>
                    <!-- <v-text-field
                    v-model="collection.DefaultSizesClassic "
                    :rules="nameRules"
                    label=" Размеры |Классические| "
                    required v-if="collection.ClassicSize">
                    </v-text-field> -->

                    <v-checkbox
                    v-model="collection.RoundSize"
                    label="Круги">
                    </v-checkbox>

                    <add-size v-on:set-sizes="onSetRound" :items="collection.DefaultSizesRound" v-if="collection.RoundSize"></add-size>
                    <!-- <v-text-field
                    v-model="collection.DefaultSizesRound"
                    :rules="nameRules"
                    label=" Размеры |Круги| "
                    required v-if="collection.RoundSize">
                    </v-text-field> -->

                    <v-checkbox
                    v-model="collection.ComplectSize"
                    label="Комплекты">
                    </v-checkbox>

                    <add-size v-on:set-sizes="onSetComplect" :items="collection.DefaultSizesComplect" v-if="collection.ComplectSize"></add-size>
                    <!-- <v-text-field
                    v-model="collection.DefaultSizesComplect"
                    :rules="nameRules"
                    label=" Размеры |Комплекты| "
                    required v-if="collection.ComplectSize">
                    </v-text-field> -->

                    <v-btn
                    :disabled="!valid"
                    @click="save">
                    Сохранить
                    </v-btn>
                    <v-btn @click="remove">Удалить</v-btn>
                </v-form>
            </v-flex>
            <v-spacer class="black"></v-spacer>

            <v-flex xs12 md12>
                <div class="headline">Дизайны:</div>
                <v-layout row wrap>
                    <v-flex md3 v-for="carpet in collection.Carpets" :key="carpet.CarpetId">
                        <collection-design-card :carpet="carpet"></collection-design-card>
                    </v-flex>
                </v-layout>
            </v-flex>
        </v-layout>
    </v-container>
</template>

<script>
import CollectionDesignCard from '../components/Collection/CollectionDesignCard'
import Autocomplete from '../components/TextFieldAuto'
import AddSize from '../components/AddSize'

export default {
    data(){
        return{
            valid: true,
            nameRules: [
                v => !!v || 'Обязательно к заполнению',
                v => (v && v.length <= 100) || 'Не более 100 символов',
                v => (v && v.length > 0) || 'Не более 100 символов'
            ],
            sampleRules: [
                v => !!v || 'Обязательно к заполнению',
                v => (v && v.length <= 100) || 'Не более 100 символов'
            ]
        }
    },
    props:{
        'id':{
            type: Number,
            required: true
        }
    },
    computed:{
        collection(){
            return this.$store.getters.getCollectionDetail
        },
        countrys(){
            return this.$store.getters.getCountrys
        },
        densitys(){
            return this.$store.getters.getDensitys
        },
        manufacturers(){
            return this.$store.getters.getManufacturers
        },
        materials(){
            return this.$store.getters.getMaterials
        },
        pileHeights(){
            return this.$store.getters.getPileHeights
        }
    },
    created(){
        this.$http.get('https://localhost:44346/api/collections/' + this.id)
        .then(response => {
            console.log(response)
            this.$store.commit('setCollectionDetail', response.data)
        })
        .catch(error => {
            console.log(error)
        })


    },
    methods:{
        save(){
        this.$http.post('https://localhost:44346/api/collections/update', this.collection)
        .then(response => {
            console.log(response);
            this.$router.go(-1)
            this.$notify({
                group: 'foo',
                type: 'success',
                title: 'Collection updated.',
                text: 'Waer! it`s ok!',
                duration: 10000
            });
        })
        .catch(error => {
            console.log(error)
            this.$notify({
                group: 'foo',
                type: 'error',
                title: 'Something went wrong. Try again.',
                text: 'Waer! it`s ok!',
                duration: 10000
            });
        })
        },
        remove(){
            //this.$router.push('collections')
            this.$http.post('https://localhost:44346/api/collections/remove', this.collection)
            .then(response => {
                this.$router.go(-1)
            })
            .catch(error => {
                console.log(error)
            })
        },
        onSetCountry(argument){
            this.collection.Country = argument
        },
        onSetDensity(argument){
            this.collection.Density = argument
        },
        onSetManufacturer(argument){
            this.collection.Manufacturer = argument
        },
        onSetMaterial(argument){
            this.collection.Material = argument
        },
        onSetPileHeight(argument){
            this.collection.PileHeight = argument
        },
        onSetLane(argument){
            this.collection.DefaultSizesLane = argument
        },
        onSetClassic(argument){
            this.collection.DefaultSizesClassic = argument
        },
        onSetRound(argument){
            this.collection.DefaultSizesRound = argument
        },
        onSetComplect(argument){
            this.collection.DefaultSizesComplect = argument
        }
    },
    components:{
        CollectionDesignCard,
        Autocomplete,
        AddSize
    }
}
</script>

<style lang="sass" scoped>

</style>